import axios from "axios";

const BASE = "http://localhost:8080/api/github";

const getAuthHeader = () => ({
  headers: {
    Authorization: "Bearer " + localStorage.getItem("token"),
    "Content-Type": "application/json"
  },
});

export const fetchLoggedUser = async () => {
  return axios.get(`${BASE}/me`, getAuthHeader());
};
export const uploadFile = (payload) =>
  axios.post(`${BASE}/upload`, payload, getAuthHeader());

export const fetchUserRepos = async () => {
  return axios.get(`${BASE}/repos`, getAuthHeader());
};
export const fetchCommits = (payload) => {
  return axios.post(`${BASE}/commits`, payload, getAuthHeader());
};

// ✅ ONLY ONE PR API — CORRECT ONE
export const fetchPRStatus = async (payload) => {
  return axios.post(`${BASE}/prs/status`, payload, getAuthHeader());
};
export const fetchPRHeatmap = (payload) =>
  axios.post(`${BASE}/prs/heatmap`, payload, getAuthHeader());

export const fetchMergeHeatmap = (payload) =>
  axios.post(`${BASE}/merge/heatmap`, payload, getAuthHeader());

export const fetchLiveCommits = (payload) => {
  return axios.post(`${BASE}/live/commits`, payload, getAuthHeader());
};
